            Describe.Lean(DescribeId.Create("native-table-exposed-exec-table"), DeclarationHandle.Create("D5/S3/Arith/FibonacciAtomic/NativeContinuation/Acquisition/NativeBinaryTable.exec_table"), H("exec_table"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("The complete fixed table program starts with the explicit input, physically produces all packed rows in register zero, and uses at most 256 times the square of the horizon plus one stack instructions."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("native-binary-table"), DeclarationHandle.Create("D5/S3/Arith/FibonacciAtomic/NativeContinuation/Acquisition/NativeBinaryTable.native_binary_table"), H("Physical acquisition of every original suffix row"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("theorem native_binary_table (L : \u2115) (A : Fin L \u2192 Finset Window) (B : Finset Bool) :     let as := List.ofFn A     (input B as).length = 2 + 5 * L \u2227     (records B as).length = (L + 1) * (6 * L + 5) \u2227     decodeTable L (records B as) = table B as \u2227     (\u2200 (t : Fin (L + 1)) (s : Bool),       (decodeTable L (records B as))[t.val]? = some (counts B (as.drop t.val)) \u2227       entry (counts B (as.drop t.val)) s = (completions B (as.drop t.val) s).card \u2227       entry (counts B (as.drop t.val)) s \u2264 5 ^ (L - t.val)) \u2227     \u2203 time tape, time \u2264 2097152 * (L + 1) ^ 4 \u2227       Complexity.runInput binaryMachine time (input B as) = some (true, tape) \u2227       tape.output = records B as")), Paragraph(Text("The decoded output equals the original natural suffix table at every position. Each entry counts original successful words and is bounded by five to the remaining horizon. The physical program runs within 2097152 times the fourth power of the horizon plus one. Its complete counted stack execution, including all row storage and output, is bounded by 256 times the square of the horizon plus one."))), DescribeRole.Theorem)),
